import React, { useEffect, useState, useCallback } from 'react';
import { visitsAPI, visitorsAPI, hostsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import { useNavigate, useLocation } from 'react-router-dom';

const STATUS_OPTIONS = ['pending','approved','refused','ongoing','completed','cancelled'];
const STATUS_LABELS  = { pending:'En attente', approved:'Approuvée', refused:'Refusée', ongoing:'En cours', completed:'Terminée', cancelled:'Annulée' };

function Toast({ msg, type, onDone }) {
  useEffect(() => { const t = setTimeout(onDone, 2500); return () => clearTimeout(t); }, [onDone]);
  return <div className={`toast ${type}`}>{msg}</div>;
}

export default function Visits() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [visits, setVisits]       = useState([]);
  const [visitors, setVisitors]   = useState([]);
  const [hosts, setHosts]         = useState([]);
  const [loading, setLoading]     = useState(true);
  const [filterStatus, setFilter] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editVisit, setEditVisit] = useState(null);
  const [toast, setToast]         = useState(null);
  const [form, setForm] = useState({
    visitor_id:'', host_id:'', purpose:'', scheduled_at:'', notes:''
  });

  const isNew = location.pathname === '/visits/new';

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await visitsAPI.getAll(filterStatus ? { status: filterStatus } : {});
      setVisits(res.data);
    } finally { setLoading(false); }
  }, [filterStatus]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    Promise.all([visitorsAPI.getAll(), hostsAPI.getAll()]).then(([v, h]) => {
      setVisitors(v.data); setHosts(h.data);
    });
  }, []);

  useEffect(() => {
    if (isNew) openCreate();
  }, [isNew]);

  const openCreate = () => {
    setEditVisit(null);
    setForm({ visitor_id:'', host_id:'', purpose:'', scheduled_at:'', notes:'' });
    setShowModal(true);
  };

  const openEdit = (v) => {
    setEditVisit(v);
    const dt = v.scheduled_at ? new Date(v.scheduled_at).toISOString().slice(0,16) : '';
    setForm({ visitor_id: v.visitor_id, host_id: v.host_id, purpose: v.purpose||'', scheduled_at: dt, notes: v.notes||'' });
    setShowModal(true);
  };

  const handleSave = async () => {
    try {
      if (editVisit) {
        await visitsAPI.update(editVisit.id, form);
        showToast('Visite mise à jour', 'success');
      } else {
        await visitsAPI.create(form);
        showToast('Visite créée', 'success');
      }
      setShowModal(false);
      if (isNew) navigate('/visits');
      load();
    } catch (e) {
      showToast(e.response?.data?.message || 'Erreur', 'error');
    }
  };

  const handleStatus = async (id, status) => {
    try {
      await visitsAPI.updateStatus(id, status);
      showToast(`Statut: ${STATUS_LABELS[status]}`, 'success');
      load();
    } catch (e) {
      showToast(e.response?.data?.message || 'Erreur', 'error');
    }
  };

  const handleCheckIn = async (id) => {
    try {
      await visitsAPI.checkIn(id, { agent_id: user.id });
      showToast('Check-in enregistré', 'success');
      load();
    } catch (e) { showToast(e.response?.data?.message || 'Erreur', 'error'); }
  };

  const handleCheckOut = async (id) => {
    try {
      await visitsAPI.checkOut(id, { agent_id: user.id });
      showToast('Check-out enregistré', 'success');
      load();
    } catch (e) { showToast(e.response?.data?.message || 'Erreur', 'error'); }
  };

  const showToast = (msg, type) => setToast({ msg, type });

  const canEdit = ['admin','agent'].includes(user?.role);
  const canStatus = ['admin','agent','host'].includes(user?.role);
  const canCheckInOut = ['admin','agent'].includes(user?.role);

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Visites</h1>
          <p className="page-sub">{visits.length} visite{visits.length !== 1 ? 's' : ''} trouvée{visits.length !== 1 ? 's' : ''}</p>
        </div>
        {canEdit && (
          <button className="btn btn-primary" onClick={openCreate}>+ Nouvelle visite</button>
        )}
      </div>

      <div className="search-bar">
        <select
          className="search-input"
          style={{ maxWidth: 200 }}
          value={filterStatus}
          onChange={e => setFilter(e.target.value)}
        >
          <option value="">Tous les statuts</option>
          {STATUS_OPTIONS.map(s => (
            <option key={s} value={s}>{STATUS_LABELS[s]}</option>
          ))}
        </select>
      </div>

      <div className="card">
        {loading ? (
          <div className="loading">Chargement...</div>
        ) : visits.length === 0 ? (
          <div className="empty-state"><div style={{fontSize:32}}>◈</div><p>Aucune visite</p></div>
        ) : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>#</th>
                  <th>Visiteur</th>
                  <th>Hôte</th>
                  <th>Objet</th>
                  <th>Rendez-vous</th>
                  <th>Statut</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {visits.map(v => (
                  <tr key={v.id}>
                    <td style={{ color:'var(--subtle)', fontVariantNumeric:'tabular-nums' }}>{v.id}</td>
                    <td>
                      <div style={{ fontWeight: 500 }}>{v.visitor_name}</div>
                      <div style={{ fontSize: 11, color: 'var(--subtle)' }}>{v.visitor_email}</div>
                    </td>
                    <td>
                      <div>{v.host_name}</div>
                      <div style={{ fontSize: 11, color: 'var(--subtle)' }}>{v.department}</div>
                    </td>
                    <td style={{ color:'var(--muted)', maxWidth:140, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                      {v.purpose || '—'}
                    </td>
                    <td style={{ whiteSpace:'nowrap', color:'var(--muted)' }}>
                      {new Date(v.scheduled_at).toLocaleString('fr-MA', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' })}
                    </td>
                    <td><span className={`badge badge-${v.status}`}>{STATUS_LABELS[v.status]}</span></td>
                    <td>
                      <div style={{ display:'flex', gap:6, flexWrap:'wrap' }}>
                        {canEdit && (
                          <button className="btn btn-outline btn-sm" onClick={() => openEdit(v)}>Modifier</button>
                        )}
                        {canCheckInOut && v.status === 'approved' && (
                          <button className="btn btn-sm" style={{ background:'var(--blue-bg)', color:'var(--blue)', border:'1px solid rgba(27,63,122,0.2)' }} onClick={() => handleCheckIn(v.id)}>Check-in</button>
                        )}
                        {canCheckInOut && v.status === 'ongoing' && (
                          <button className="btn btn-sm" style={{ background:'var(--green-bg)', color:'var(--green)', border:'1px solid rgba(26,92,56,0.2)' }} onClick={() => handleCheckOut(v.id)}>Check-out</button>
                        )}
                        {canStatus && v.status === 'pending' && (
                          <>
                            <button className="btn btn-sm" style={{ background:'var(--green-bg)', color:'var(--green)', border:'1px solid rgba(26,92,56,0.2)' }} onClick={() => handleStatus(v.id,'approved')}>Approuver</button>
                            <button className="btn btn-danger btn-sm" onClick={() => handleStatus(v.id,'refused')}>Refuser</button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setShowModal(false)}>
          <div className="modal">
            <h3>{editVisit ? 'Modifier la visite' : 'Nouvelle visite'}</h3>

            <div className="form-field">
              <label>Visiteur</label>
              <select value={form.visitor_id} onChange={e => setForm(f=>({...f, visitor_id: e.target.value}))}>
                <option value="">Sélectionner un visiteur</option>
                {visitors.map(v => <option key={v.id} value={v.id}>{v.name} — {v.email}</option>)}
              </select>
            </div>

            <div className="form-field">
              <label>Hôte</label>
              <select value={form.host_id} onChange={e => setForm(f=>({...f, host_id: e.target.value}))}>
                <option value="">Sélectionner un hôte</option>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name} — {h.department}</option>)}
              </select>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label>Date et heure</label>
                <input type="datetime-local" value={form.scheduled_at} onChange={e => setForm(f=>({...f, scheduled_at: e.target.value}))} />
              </div>
              <div className="form-field">
                <label>Objet de la visite</label>
                <input type="text" placeholder="Réunion, entretien..." value={form.purpose} onChange={e => setForm(f=>({...f, purpose: e.target.value}))} />
              </div>
            </div>

            <div className="form-field">
              <label>Notes (optionnel)</label>
              <textarea rows={3} value={form.notes} onChange={e => setForm(f=>({...f, notes: e.target.value}))} />
            </div>

            <div className="modal-actions">
              <button className="btn btn-outline" onClick={() => { setShowModal(false); if(isNew) navigate('/visits'); }}>Annuler</button>
              <button className="btn btn-primary" onClick={handleSave}>
                {editVisit ? 'Enregistrer' : 'Créer'}
              </button>
            </div>
          </div>
        </div>
      )}

      {toast && <Toast msg={toast.msg} type={toast.type} onDone={() => setToast(null)} />}
    </div>
  );
}
